82	
83	    /**
84	     * Dedicated audit logger. On a successful owner create an audit line carrying the owner id,
85	     * the {@code memberId} and the {@code registrationDate} is emitted to this named logger.
86	     */
87	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
88	
89	    /**
90	     * Dedicated notification logger. On a successful owner create a welcome-notification line
91	     * carrying the owner id and the {@code memberId} is enqueued by emitting it to this named logger.
92	     */
