166	    /**
167	     * Rejects an owner payload that is missing or blank in any of the required fields
168	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
169	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
170	     * value as present; this guard closes that gap so a blank in any required field is
171	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
172	     * the name of each offending field.
173	     */
174	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
175	        List<String> missing = new ArrayList<>();
176	        if (isBlank(ownerFieldsDto.getFirstName())) {
177	            missing.add("firstName");
178	        }
179	        if (isBlank(ownerFieldsDto.getLastName())) {
180	            missing.add("lastName");
181	        }
182	        if (isBlank(normalizedAddress)) {
183	            missing.add("address");
184	        }
185	        if (isBlank(ownerFieldsDto.getCity())) {
186	            missing.add("city");
187	        }
188	        if (isBlank(ownerFieldsDto.getTelephone())) {
189	            missing.add("telephone");
190	        }
191	        if (!missing.isEmpty()) {
192	            throw new MissingOwnerFieldsException(missing);
193	        }
194	    }
