200	    /**
201	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
202	     */
203	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
204	
205	    /**
206	     * Required national-number length per country calling code. When the normalized E.164 number
207	     * begins with one of these codes, the digits that follow must number exactly the mapped value:
208	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Codes absent from
209	     * this map carry no per-country length rule beyond the generic E.164 8-to-15-digit bound.
210	     */
211	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
212	        "+61", 9,
213	        "+1", 10);
214	
215	    /**
216	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
217	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
218	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
219	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
220	     * stored as '+61412345678'. When the country code has a known national-number length ('+61'
221	     * requires 9 national digits, '+1' requires 10) the national digits must match it exactly. A
222	     * value that cannot form a valid E.164 number, or whose national length is wrong for its
223	     * country, is rejected via {@link InvalidTelephoneException}, which the exception handler
224	     * translates to a 400.
225	     */
226	    private static String normalizeTelephone(String telephone) {
227	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
228	        String e164;
229	        if (cleaned.startsWith("+")) {
230	            e164 = cleaned;
231	        } else {
232	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
233	            e164 = "+61" + national;
234	        }
235	        if (!E164_PATTERN.matcher(e164).matches()) {
236	            throw new InvalidTelephoneException(telephone);
237	        }
238	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
239	            String code = rule.getKey();
240	            if (e164.startsWith(code)) {
241	                int nationalLength = e164.length() - code.length();
242	                if (nationalLength != rule.getValue()) {
243	                    throw new InvalidTelephoneException(telephone);
244	                }
245	                break;
246	            }
247	        }
248	        return e164;
249	    }
