275	    /**
276	     * Validates an owner's optional postcode. A {@code null} postcode is left as-is (the field is
277	     * optional). When present it must be exactly four digits; and when the owner's city maps to a
278	     * known region it must fall within that region's inclusive postcode range (NSW 2000-2099, VIC
279	     * 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An
280	     * invalid or out-of-range value is rejected via {@link InvalidPostcodeException}, which the
281	     * exception handler translates to a 400.
282	     */
283	    private static void validatePostcode(String city, String postcode) {
284	        if (postcode == null) {
285	            return;
286	        }
287	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
288	            throw new InvalidPostcodeException(postcode);
289	        }
290	        String region = CITY_REGION.get(city);
291	        if (region == null) {
292	            return;
293	        }
294	        int[] range = REGION_POSTCODES.get(region);
295	        int value = Integer.parseInt(postcode);
296	        if (value < range[0] || value > range[1]) {
297	            throw new InvalidPostcodeException(postcode);
298	        }
299	    }
