301	    /**
302	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
303	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
304	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
305	     */
306	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
307	
308	    /**
309	     * Disposable-email domains that an owner's email may not use. An address whose domain (the part
310	     * after the final {@code @}, compared case-insensitively) is one of these is rejected. Kept as a
311	     * fixed set so the block list is explicit and easy to extend.
312	     */
313	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
314	        "mailinator.com",
315	        "tempmail.com",
316	        "guerrillamail.com");
317	
318	    /**
319	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
320	     * optional). When present it must be a syntactically valid address whose domain is not on the
321	     * disposable-domain block list; a valid value is lower-cased so it is stored and returned in
322	     * canonical form. An invalid or disposable-domain value is rejected via
323	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
324	     */
325	    private static String normalizeEmail(String email) {
326	        if (email == null) {
327	            return null;
328	        }
329	        if (!EMAIL_PATTERN.matcher(email).matches()) {
330	            throw new InvalidEmailException(email);
331	        }
332	        String normalized = email.toLowerCase(Locale.ROOT);
333	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
334	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
335	            throw new InvalidEmailException(email);
336	        }
337	        return normalized;
338	    }
