340	    /**
341	     * The single derived identity of an owner: the 64-character lower-case SHA-256 hex digest over
342	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, into which all
343	     * duplicate detection is consolidated. Two owners are the same identity only when this whole key
344	     * matches: because the normalized telephone is part of the pre-image, two owners who share a
345	     * surname (same soundex) and postcode but carry different telephones have different identity
346	     * keys. A {@code null} email contributes an empty middle segment. Under version 2 the owner's
347	     * {@link #regionCodeV2 version-2 region code} is mixed into the pre-image as a trailing segment,
348	     * so the key differs from its version-1 value. This is the value returned to callers as the
349	     * {@code identityKey} inside the {@code identity} object.
350	     */
351	    private static String identityKeyFor(String normalizedTelephone, String normalizedEmail, String lastName,
352	                                         String regionV2) {
353	        String preimage = normalizedTelephone + "|" + (normalizedEmail == null ? "" : normalizedEmail)
354	            + "|" + soundex(lastName) + "|" + regionV2;
355	        return sha256Hex(preimage);
356	    }
357	
358	    /**
359	     * The American Soundex code of a name: its first letter followed by up to three digits encoding
360	     * the remaining consonants (b/f/p/v->1, c/g/j/k/q/s/x/z->2, d/t->3, l->4, m/n->5, r->6), with
361	     * adjacent duplicate codes collapsed, vowels (and y) resetting the run, and h/w transparent so
362	     * consonants they separate are still treated as adjacent. The result is padded with zeros to
363	     * exactly four characters. A {@code null} or letterless name yields the empty string.
364	     */
365	    private static String soundex(String name) {
366	        if (name == null) {
367	            return "";
368	        }
369	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
370	        if (letters.isEmpty()) {
371	            return "";
372	        }
373	        StringBuilder code = new StringBuilder();
374	        code.append(letters.charAt(0));
375	        char prev = soundexCode(letters.charAt(0));
376	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
377	            char c = letters.charAt(i);
378	            if (c == 'H' || c == 'W') {
379	                continue;
380	            }
381	            char digit = soundexCode(c);
382	            if (digit != '0' && digit != prev) {
383	                code.append(digit);
384	            }
385	            prev = digit;
386	        }
387	        while (code.length() < 4) {
388	            code.append('0');
389	        }
390	        return code.toString();
391	    }
392	
393	    /**
394	     * The Soundex digit for a single upper-case letter, or {@code '0'} for a vowel, y, h or w (which
395	     * carry no code).
396	     */
397	    private static char soundexCode(char c) {
398	        return switch (c) {
399	            case 'B', 'F', 'P', 'V' -> '1';
400	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
401	            case 'D', 'T' -> '3';
402	            case 'L' -> '4';
403	            case 'M', 'N' -> '5';
404	            case 'R' -> '6';
405	            default -> '0';
406	        };
407	    }
408	
409	    /**
410	     * The full lower-case SHA-256 hex digest (64 characters) of the UTF-8 bytes of {@code value}.
411	     */
412	    private static String sha256Hex(String value) {
413	        try {
414	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
415	            StringBuilder sb = new StringBuilder(digest.length * 2);
416	            for (byte b : digest) {
417	                sb.append(String.format("%02x", b));
418	            }
419	            return sb.toString();
420	        } catch (NoSuchAlgorithmException ex) {
421	            throw new IllegalStateException("SHA-256 not available", ex);
422	        }
423	    }
