425	    /**
426	     * Rejects a create whose derived identity collides with an existing owner's, reported via
427	     * {@link DuplicateTelephoneException} which the handler translates to a 409. Duplicate detection
428	     * is now the single identity key: the new owner's {@link #identityKeyFor identityKey} (the
429	     * SHA-256 over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}) is
430	     * compared against each existing owner's, ignoring owners flagged deleted. The email-domain
431	     * block list has already been applied while normalizing the email, so it takes effect first. An
432	     * existing telephone that cannot form a valid E.164 number is skipped rather than colliding.
433	     * Because the telephone is part of the key, two owners with the same surname and postcode but
434	     * different telephones no longer collide here - they are surfaced as a soft match instead. The
435	     * former separate telephone, email and household 409 blocks are all subsumed by this key.
436	     */
437	    private void rejectDuplicateIdentity(String normalizedTelephone, String normalizedEmail, String lastName,
438	                                         String regionV2) {
439	        String identityKey = identityKeyFor(normalizedTelephone, normalizedEmail, lastName, regionV2);
440	        for (Owner existing : this.clinicService.findAllOwners()) {
441	            if (existing.isDeleted()) {
442	                continue;
443	            }
444	            String existingTelephone;
445	            try {
446	                existingTelephone = normalizeTelephone(existing.getTelephone());
447	            } catch (InvalidTelephoneException ex) {
448	                continue;
449	            }
450	            String existingEmail = existing.getEmail() == null ? null : existing.getEmail().toLowerCase(Locale.ROOT);
451	            String existingRegion = regionCodeV2(existing.getCity(), existing.getPostcode());
452	            String existingKey = identityKeyFor(existingTelephone, existingEmail, existing.getLastName(),
453	                existingRegion);
454	            if (identityKey.equals(existingKey)) {
455	                throw new DuplicateTelephoneException(normalizedTelephone);
456	            }
457	        }
458	    }
