460	    /**
461	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
462	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
463	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
464	     * spacing do not defeat the duplicate-household check.
465	     */
466	    private static String collapse(String value) {
467	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
468	    }
469	
470	    /**
471	     * Normalizes an owner's address into a canonical form applied on every create: leading and
472	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
473	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
474	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
475	     * and returned, and is the form every address comparison (duplicate-household detection and the
476	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
477	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
478	     * so normalizing an already-normalized address is a no-op.
479	     */
480	    private static String normalizeAddress(String address) {
481	        if (address == null) {
482	            return "";
483	        }
484	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
485	        if (collapsed.isEmpty()) {
486	            return "";
487	        }
488	        String[] tokens = collapsed.split(" ");
489	        StringBuilder sb = new StringBuilder(collapsed.length());
490	        for (int i = 0; i < tokens.length; i++) {
491	            String token = tokens[i];
492	            switch (token) {
493	                case "ST" -> token = "STREET";
494	                case "RD" -> token = "ROAD";
495	                case "AVE" -> token = "AVENUE";
496	                default -> {
497	                }
498	            }
499	            if (i > 0) {
500	                sb.append(' ');
501	            }
502	            sb.append(token);
503	        }
504	        return sb.toString();
505	    }
