507	    /**
508	     * Derives an owner's region code from its postcode, falling back to its city. A present postcode
509	     * that falls in a known region's inclusive 4-digit range wins (NSW 2000-2099, VIC 3000-3099, QLD
510	     * 4000-4099); otherwise the fixed city-to-region table is consulted (Sydney -> NSW, Melbourne ->
511	     * VIC, Brisbane -> QLD); a value resolved by neither is {@code "UNKNOWN"}. This is the single
512	     * region derivation shared by the {@code memberId} and the owner's locality.
513	     */
514	    private static String deriveRegion(String city, String postcode) {
515	        if (postcode != null) {
516	            try {
517	                int pc = Integer.parseInt(postcode.trim());
518	                for (Map.Entry<String, int[]> range : REGION_POSTCODES.entrySet()) {
519	                    int[] bounds = range.getValue();
520	                    if (pc >= bounds[0] && pc <= bounds[1]) {
521	                        return range.getKey();
522	                    }
523	                }
524	            } catch (NumberFormatException ignored) {
525	                // not a numeric postcode; fall back to the city-to-region table
526	            }
527	        }
528	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
529	    }
530	
531	    /**
532	     * The fixed version tag mixed into the region code of every version-2 identifier
533	     * ({@code memberId}, {@code householdId} and {@code identityKey}), so no value produced under
534	     * version 1 is produced again. It appears only inside those identifiers; the user-facing
535	     * {@code locality}, {@code timezone} and owner-segment region remain the plain region code.
536	     */
537	    private static final String IDENTITY_VERSION_TAG = "V2";
538	
539	    /**
540	     * The version-2 region code folded into the owner's identifiers: the plain region from
541	     * {@link #deriveRegion} mixed with the fixed {@value #IDENTITY_VERSION_TAG} tag (e.g. the plain
542	     * region {@code "NSW"} becomes {@code "V2NSW"}). This tagged value is only ever embedded inside
543	     * an identifier; the plain region is what the owner's locality and timezone report.
544	     */
545	    private static String regionCodeV2(String city, String postcode) {
546	        return IDENTITY_VERSION_TAG + deriveRegion(city, postcode);
547	    }
548	
549	    /**
550	     * Builds the {@code memberId} for a newly created owner, formatted {@code '<REGION><FY><HASH8><CHK>'}
551	     * where {@code REGION} is the region code derived from the owner's postcode (falling back to its
552	     * city), {@code FY} is the 2-digit fiscal year of the {@code registrationDate} (matching the owner's
553	     * {@code fiscalYear}), {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
554	     * {@code normalizedTelephone + lastName} (the same HASH8 used by the region-and-hash identity), and
555	     * {@code CHK} is a single Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>}
556	     * (e.g. {@code 'NSW271A2B3C4D5'}). This is a stable identity: it carries no sequence number and
557	     * depends only on the owner's own region, fiscal year, telephone and surname.
558	     */
559	    private static String memberIdFor(String region, LocalDate registrationDate,
560	                                      String normalizedTelephone, String lastName) {
561	        String fy = String.format("%02d", fiscalYearOf(registrationDate) % 100);
562	        String hash8 = sha256HexPrefix(normalizedTelephone + lastName, 8);
563	        String base = region + fy + hash8;
564	        return base + luhnCheckDigit(base);
565	    }
566	
567	    /**
568	     * The single Luhn check digit (0-9) computed over the digits contained in {@code value};
569	     * non-digit characters are ignored.
570	     */
571	    private static int luhnCheckDigit(String value) {
572	        int sum = 0;
573	        boolean dbl = true;
574	        for (int i = value.length() - 1; i >= 0; i--) {
575	            char c = value.charAt(i);
576	            if (c < '0' || c > '9') {
577	                continue;
578	            }
579	            int d = c - '0';
580	            if (dbl) {
581	                d *= 2;
582	                if (d > 9) {
583	                    d -= 9;
584	                }
585	            }
586	            sum += d;
587	            dbl = !dbl;
588	        }
589	        return (10 - (sum % 10)) % 10;
590	    }
591	
592	    /**
593	     * De-duplicates a freshly computed {@code memberId} against the ids already carried by existing
594	     * owners. When the base id is unused it is returned unchanged; otherwise {@code '-<n>'} is appended
595	     * with the smallest {@code n} of 2 or more that yields an id no existing owner already holds. The
596	     * count reflects the state prior to this create.
597	     */
598	    private String deduplicateMemberId(String baseId) {
599	        Set<String> existingIds = new HashSet<>();
600	        for (Owner existing : this.clinicService.findAllOwners()) {
601	            String id = existing.getMemberId();
602	            if (id != null) {
603	                existingIds.add(id);
604	            }
605	        }
606	        if (!existingIds.contains(baseId)) {
607	            return baseId;
608	        }
609	        int n = 2;
610	        while (existingIds.contains(baseId + "-" + n)) {
611	            n++;
612	        }
613	        return baseId + "-" + n;
614	    }
615	
616	    /**
617	     * Returns the first {@code hexChars} upper-case hex characters of the SHA-256 digest of the UTF-8
618	     * bytes of {@code value}.
619	     */
620	    private static String sha256HexPrefix(String value, int hexChars) {
621	        try {
622	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
623	            StringBuilder sb = new StringBuilder(hexChars);
624	            for (byte b : digest) {
625	                if (sb.length() >= hexChars) {
626	                    break;
627	                }
628	                sb.append(String.format("%02X", b));
629	            }
630	            return sb.substring(0, hexChars);
631	        } catch (NoSuchAlgorithmException ex) {
632	            throw new IllegalStateException("SHA-256 not available", ex);
633	        }
634	    }
635	
636	    /**
637	     * The fiscal year, as a four-digit year, of a business-day-adjusted date. The fiscal year
638	     * starts on 1 July and is labelled by the calendar year in which it ends: a date on or after
639	     * 1 July belongs to the fiscal year ending the following calendar year, while an earlier date
640	     * belongs to the fiscal year ending in its own year.
641	     */
642	    private static int fiscalYearOf(LocalDate date) {
643	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
644	    }
645	
646	    /**
647	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
648	     * its {@code postcode} - the same pair used to detect a shared household. It is the first 12
649	     * lower-case hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Because
650	     * it is a pure function of that pair, every owner in the same household - whether created first
651	     * or joining later via {@code sharesHousehold} - receives the identical, non-blank identifier
652	     * without needing to read any other owner's value. A {@code null} postcode contributes an empty
653	     * segment. Under version 2 the {@link #regionCodeV2 version-2 region code} is mixed in as a
654	     * trailing segment, so the value differs from its version-1 form. Because that region is derived
655	     * from the same postcode (falling back to the city), household members still share it.
656	     */
657	    private static String householdIdFor(String lastName, String postcode, String regionV2) {
658	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode) + "|" + regionV2;
659	        try {
660	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
661	            StringBuilder sb = new StringBuilder(12);
662	            for (byte b : digest) {
663	                if (sb.length() >= 12) {
664	                    break;
665	                }
666	                sb.append(String.format("%02x", b));
667	            }
668	            return sb.substring(0, 12);
669	        } catch (NoSuchAlgorithmException ex) {
670	            throw new IllegalStateException("SHA-256 not available", ex);
671	        }
672	    }
673	
674	    /**
675	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
676	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
677	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
678	     */
679	    private int countNamesakes(String firstName, String lastName) {
680	        int count = 0;
681	        for (Owner existing : this.clinicService.findAllOwners()) {
682	            if (firstName.equalsIgnoreCase(existing.getFirstName())
683	                && lastName.equalsIgnoreCase(existing.getLastName())) {
684	                count++;
685	            }
686	        }
687	        return count;
688	    }
