690	    /**
691	     * Counts the members of the household the new owner will belong to, as it stands after this
692	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
693	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
694	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
695	     * stored on the owner as its {@code householdMemberCount}.
696	     */
697	    private int countHouseholdMembers(String householdId) {
698	        int count = 1;
699	        for (Owner existing : this.clinicService.findAllOwners()) {
700	            if (householdId.equals(existing.getHouseholdId())) {
701	                count++;
702	            }
703	        }
704	        return count;
705	    }
