707	    /**
708	     * Finds an existing owner that makes the new owner a <em>possible</em> (soft) duplicate: one
709	     * that is not a hard identity collision but whose {@code lastName} has the same
710	     * {@link #soundex soundex} code as the new owner's and whose {@code postcode} matches, while its
711	     * {@link #identityKeyFor identityKey} differs. The new owner's postcode must be present for a
712	     * soft match to be possible. When several existing owners qualify the one with the lowest id is
713	     * chosen. Returns the matching owner's id, or {@code null} when there is no soft match. This is
714	     * evaluated after the hard-duplicate check has already passed, so any surviving owner sharing the
715	     * surname's soundex and postcode necessarily has a different identity key (typically a different
716	     * telephone). A caller that declares {@code sharesHousehold} is deliberately joining an existing
717	     * household, so it is not flagged as a suspected duplicate.
718	     */
719	    private Integer findPossibleDuplicateOf(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone,
720	                                            String normalizedEmail) {
721	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
722	            return null;
723	        }
724	        String postcode = ownerFieldsDto.getPostcode();
725	        if (postcode == null) {
726	            return null;
727	        }
728	        String lastName = ownerFieldsDto.getLastName();
729	        if (lastName == null) {
730	            return null;
731	        }
732	        String regionV2 = regionCodeV2(ownerFieldsDto.getCity(), postcode);
733	        String identityKey = identityKeyFor(normalizedTelephone, normalizedEmail, lastName, regionV2);
734	        String soundex = soundex(lastName);
735	        Integer matchId = null;
736	        for (Owner existing : this.clinicService.findAllOwners()) {
737	            if (existing.isDeleted()) {
738	                continue;
739	            }
740	            if (!soundex.equals(soundex(existing.getLastName()))) {
741	                continue;
742	            }
743	            if (!postcode.equals(existing.getPostcode())) {
744	                continue;
745	            }
746	            String existingTelephone;
747	            try {
748	                existingTelephone = normalizeTelephone(existing.getTelephone());
749	            } catch (InvalidTelephoneException ex) {
750	                continue;
751	            }
752	            String existingEmail = existing.getEmail() == null ? null : existing.getEmail().toLowerCase(Locale.ROOT);
753	            String existingRegion = regionCodeV2(existing.getCity(), existing.getPostcode());
754	            String existingKey = identityKeyFor(existingTelephone, existingEmail, existing.getLastName(),
755	                existingRegion);
756	            if (identityKey.equals(existingKey)) {
757	                continue;
758	            }
759	            if (existing.getId() != null && (matchId == null || existing.getId() < matchId)) {
760	                matchId = existing.getId();
761	            }
762	        }
763	        return matchId;
764	    }
