766	    /**
767	     * The tenure, in elapsed fiscal years, that an owner must exceed before its tenure contributes
768	     * membership points. Tenure is measured from the owner's {@code registrationDate}, so a newly
769	     * created owner (whose tenure is zero) never satisfies this and thus never earns the tenure
770	     * points on create.
771	     */
772	    private static final int TENURE_POINTS_THRESHOLD_FISCAL_YEARS = 1;
773	
774	    /**
775	     * The household size (number of members) at or above which an owner earns the household points.
776	     */
777	    private static final int HOUSEHOLD_POINTS_THRESHOLD = 3;
778	
779	    /**
780	     * Computes the {@code membershipPoints} for an owner. Points start at 0, gain 2 when an email is
781	     * present, gain 1 when the owner's {@code namesakeCount} is 0, gain 2 when the owner's household
782	     * has {@value #HOUSEHOLD_POINTS_THRESHOLD} or more members, and gain 3 when the owner's tenure
783	     * (elapsed fiscal years since its {@code registrationDate}) exceeds
784	     * {@value #TENURE_POINTS_THRESHOLD_FISCAL_YEARS}. Because a newly created owner has zero tenure,
785	     * the tenure points never apply on create.
786	     * Evaluated after the owner's email, namesakeCount, householdMemberCount and registrationDate
787	     * have been set.
788	     */
789	    private static int membershipPointsFor(Owner owner) {
790	        int points = 0;
791	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
792	            points += 2;
793	        }
794	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
795	            points += 1;
796	        }
797	        if (owner.getHouseholdMemberCount() != null
