59	    /**
60	     * Derive the owner's locality (region) from its postcode, falling back to its city. This shares
61	     * the identity's region derivation, where the postcode range takes precedence (NSW 2000-2099, VIC
62	     * 3000-3099, QLD 4000-4099) and the city-to-region table (Sydney->NSW, Melbourne->VIC,
63	     * Brisbane->QLD) is the fallback, otherwise "UNKNOWN". This is the same region embedded as the
64	     * {@code REGION} prefix of the owner's {@code memberId}.
65	     */
66	    default String deriveLocality(Owner owner) {
67	        if (owner == null) {
68	            return null;
69	        }
70	        String postcode = owner.getPostcode();
71	        if (postcode != null) {
72	            try {
73	                int pc = Integer.parseInt(postcode.trim());
74	                if (pc >= 2000 && pc <= 2099) {
75	                    return "NSW";
76	                }
77	                if (pc >= 3000 && pc <= 3099) {
78	                    return "VIC";
79	                }
80	                if (pc >= 4000 && pc <= 4099) {
81	                    return "QLD";
82	                }
83	            }
84	            catch (NumberFormatException ignored) {
85	                // not a numeric postcode; fall back to the city-to-region table
86	            }
87	        }
88	        String city = owner.getCity();
89	        if ("Sydney".equals(city)) {
90	            return "NSW";
91	        }
92	        if ("Melbourne".equals(city)) {
93	            return "VIC";
94	        }
95	        if ("Brisbane".equals(city)) {
96	            return "QLD";
97	        }
98	        return "UNKNOWN";
99	    }
