101	    /**
102	     * Derive the owner's marketing segment, formatted {@code '<TIER>_<AREA>'}. TIER is
103	     * {@code "PREMIUM"} when the owner's {@code membershipLevel} is 3 or more, otherwise
104	     * {@code "STANDARD"} (a missing membershipLevel counts as below 3). AREA is {@code "METRO"}
105	     * when the owner's locality is a known region (NSW, VIC or QLD), otherwise {@code "REGIONAL"}.
106	     * Returns null when the owner is absent.
107	     */
108	    default String deriveOwnerSegment(Owner owner) {
109	        if (owner == null) {
110	            return null;
111	        }
112	        Integer membershipLevel = owner.getMembershipLevel();
113	        String tier = (membershipLevel != null && membershipLevel >= 3) ? "PREMIUM" : "STANDARD";
114	        String locality = deriveLocality(owner);
115	        boolean metro = "NSW".equals(locality) || "VIC".equals(locality) || "QLD".equals(locality);
116	        return tier + "_" + (metro ? "METRO" : "REGIONAL");
117	    }
