122	     * an email whose domain is exactly one of these, so only a subdomain of one survives to be flagged.
123	     */
124	    java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
125	        "mailinator.com",
126	        "tempmail.com",
127	        "guerrillamail.com");
