129	    /**
130	     * Derive the owner's {@code riskFlag}: true when any of these hold, otherwise false. The owner is
131	     * a possible duplicate ({@code possibleDuplicate} is true); the owner's email domain is
132	     * disposable-adjacent ({@link #isDisposableAdjacent}); or the owner's city is over its soft
133	     * capacity ({@code capacityWarning} is true, i.e. the city already held 40 or more owners when
134	     * this owner was created). Returns false when the owner is absent.
135	     */
136	    default boolean deriveRiskFlag(Owner owner) {
137	        if (owner == null) {
138	            return false;
139	        }
140	        boolean possibleDuplicate = Boolean.TRUE.equals(owner.getPossibleDuplicate());
141	        boolean overSoftCapacity = Boolean.TRUE.equals(owner.getCapacityWarning());
142	        boolean disposableAdjacent = isDisposableAdjacent(owner.getEmail());
143	        return possibleDuplicate || disposableAdjacent || overSoftCapacity;
