146	    /**
147	     * Whether an email's domain is disposable-adjacent: the domain (the part after the final
148	     * {@code @}, compared case-insensitively) is a proper subdomain of a known disposable-email
149	     * domain, i.e. it ends with {@code '.' + disposableDomain}. An exact match to a disposable domain
150	     * is rejected on create, so it never reaches here. A null or malformed email is not adjacent.
151	     */
152	    default boolean isDisposableAdjacent(String email) {
153	        if (email == null) {
154	            return false;
155	        }
156	        int at = email.lastIndexOf('@');
157	        if (at < 0) {
158	            return false;
159	        }
160	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
161	        for (String disposable : DISPOSABLE_EMAIL_DOMAINS) {
162	            if (domain.endsWith("." + disposable)) {
163	                return true;
164	            }
165	        }
166	        return false;
167	    }
