192	    /**
193	     * Derive the owner's age band from its birthDate against the registrationDate: 'MINOR' when
194	     * under 18, 'ADULT' from 18 to 64, and 'SENIOR' at 65 or older. The age is the number of whole
195	     * years between birthDate and registrationDate (falling back to the current date when the owner
196	     * has no registrationDate). Returns null when the owner or its birthDate is absent, so no
197	     * ageBand is reported.
198	     */
199	    default String deriveAgeBand(Owner owner) {
200	        if (owner == null || owner.getBirthDate() == null) {
201	            return null;
202	        }
203	        java.time.LocalDate reference = owner.getRegistrationDate() != null
204	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
205	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
206	        if (age < 18) {
207	            return "MINOR";
208	        }
209	        if (age < 65) {
210	            return "ADULT";
211	        }
212	        return "SENIOR";
213	    }
