215	    /**
216	     * Known E.164 country calling codes, longest first, used to split a stored telephone into its
217	     * country code and national digits. A number whose code is not listed falls back to a two-digit
218	     * country code, the most common E.164 length.
219	     */
220	    String[] KNOWN_CALLING_CODES = { "61", "1" };
221	
222	    /**
223	     * Format the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
224	     * the national digits grouped in threes (e.g. {@code "+61412345678"} becomes
225	     * {@code "+61 412 345 678"}). Returns null when the owner or its telephone is absent, and returns
226	     * the value unchanged when it is not in E.164 form.
227	     */
228	    default String deriveTelephoneDisplay(Owner owner) {
229	        if (owner == null || owner.getTelephone() == null) {
230	            return null;
231	        }
232	        String telephone = owner.getTelephone();
233	        if (!telephone.startsWith("+")) {
234	            return telephone;
235	        }
236	        String digits = telephone.substring(1);
237	        int codeLength = 2;
238	        for (String code : KNOWN_CALLING_CODES) {
239	            if (digits.startsWith(code) && digits.length() > code.length()) {
240	                codeLength = code.length();
241	                break;
242	            }
243	        }
244	        if (digits.length() <= codeLength) {
245	            return telephone;
246	        }
247	        String national = digits.substring(codeLength);
248	        StringBuilder display = new StringBuilder("+").append(digits, 0, codeLength);
249	        for (int i = 0; i < national.length(); i += 3) {
250	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
251	        }
252	        return display.toString();
253	    }
