255	    /**
256	     * Derive the owner's salutation: the honorific {@code title} followed by a single space and the
257	     * {@code lastName} (e.g. {@code "DR Who"}). When the owner has no title (null or blank) the
258	     * salutation is just the {@code lastName}. Returns null when the owner is absent.
259	     */
260	    default String deriveSalutation(Owner owner) {
261	        if (owner == null) {
