272	    /**
273	     * Derive the owner's fiscal year from its business-day-adjusted {@code registrationDate},
274	     * formatted {@code 'FY<YY>'} where YY is the last two digits of the fiscal year. The fiscal
275	     * year starts on 1 July and is labelled by the calendar year in which it ends, so a
276	     * registrationDate on or after 1 July belongs to the fiscal year ending the following calendar
277	     * year. Returns null when the owner or its registrationDate is absent.
278	     */
279	    default String deriveFiscalYear(Owner owner) {
280	        if (owner == null || owner.getRegistrationDate() == null) {
281	            return null;
282	        }
283	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
284	        int fiscalYear = registrationDate.getMonthValue() >= java.time.Month.JULY.getValue()
285	            ? registrationDate.getYear() + 1 : registrationDate.getYear();
286	        return String.format("FY%02d", fiscalYear % 100);
287	    }
