322	    /**
323	     * Derive the owner's version-2 {@code identityKey}: the 64-character lower-case SHA-256 hex
324	     * digest over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName) + '|' +
325	     * v2Region}, where {@code v2Region} is the {@link #deriveIdentityRegion version-2 region code}.
326	     * The telephone and email are the owner's already-normalized stored values (E.164 telephone,
327	     * lower-cased email); a null email contributes an empty middle segment. Returns null when the
328	     * owner is absent. This is the same key duplicate detection compares on create.
329	     */
330	    default String deriveIdentityKey(Owner owner) {
331	        if (owner == null) {
332	            return null;
333	        }
334	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
335	        String email = owner.getEmail() == null ? "" : owner.getEmail();
336	        return sha256Hex(telephone + "|" + email + "|" + soundex(owner.getLastName())
337	            + "|" + deriveIdentityRegion(owner));
