340	    /**
341	     * The American Soundex code of a name: its first letter followed by up to three digits encoding
342	     * the remaining consonants (b/f/p/v->1, c/g/j/k/q/s/x/z->2, d/t->3, l->4, m/n->5, r->6), with
343	     * adjacent duplicate codes collapsed, vowels (and y) resetting the run, and h/w transparent. The
344	     * result is padded with zeros to exactly four characters. A null or letterless name yields "".
345	     */
346	    private static String soundex(String name) {
347	        if (name == null) {
348	            return "";
349	        }
350	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
351	        if (letters.isEmpty()) {
352	            return "";
353	        }
354	        StringBuilder code = new StringBuilder();
355	        code.append(letters.charAt(0));
356	        char prev = soundexCode(letters.charAt(0));
357	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
358	            char c = letters.charAt(i);
359	            if (c == 'H' || c == 'W') {
360	                continue;
361	            }
362	            char digit = soundexCode(c);
363	            if (digit != '0' && digit != prev) {
364	                code.append(digit);
365	            }
366	            prev = digit;
367	        }
368	        while (code.length() < 4) {
369	            code.append('0');
370	        }
371	        return code.toString();
372	    }
373	
374	    /**
375	     * The Soundex digit for a single upper-case letter, or {@code '0'} for a vowel, y, h or w.
376	     */
377	    private static char soundexCode(char c) {
378	        return switch (c) {
379	            case 'B', 'F', 'P', 'V' -> '1';
380	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
381	            case 'D', 'T' -> '3';
382	            case 'L' -> '4';
383	            case 'M', 'N' -> '5';
384	            case 'R' -> '6';
385	            default -> '0';
386	        };
387	    }
388	
389	    /**
390	     * The full lower-case SHA-256 hex digest (64 characters) of the UTF-8 bytes of {@code value}.
391	     */
392	    private static String sha256Hex(String value) {
393	        try {
394	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
395	            StringBuilder sb = new StringBuilder(digest.length * 2);
396	            for (byte b : digest) {
397	                sb.append(String.format("%02x", b));
398	            }
399	            return sb.toString();
400	        }
401	        catch (NoSuchAlgorithmException ex) {
402	            throw new IllegalStateException("SHA-256 not available", ex);
403	        }
404	    }
